  c.save(); c.translate(0,s*0.08); c.fillStyle='rgba(0,0,0,.5)'; styOct(c,s,u); c.fill(); c.restore();
  gr=c.createLinearGradient(-s,-s,s,s); gr.addColorStop(0,T.hi); gr.addColorStop(0.45,T.mid); gr.addColorStop(1,T.lo);
